package com.yeyamo_mobile.api.payment_service.infrastructure.persistence;
import java.time.Instant;import java.util.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import jakarta.persistence.*;
@Entity@Table(name="payment_reconciliation_jobs")public class ReconciliationJobEntity{@Id private UUID id;@Column(nullable=false,length=30)private String status;@Column(name="requested_by",nullable=false,length=120)private String requestedBy;@Column(name="correlation_id",length=120)private String correlationId;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="completed_at")private Instant completedAt;@JdbcTypeCode(SqlTypes.JSON)@Column(nullable=false,columnDefinition="jsonb")private Map<String,Object>summary=new LinkedHashMap<>();protected ReconciliationJobEntity(){}public static ReconciliationJobEntity queued(String actor,String correlation){var j=new ReconciliationJobEntity();j.id=UUID.randomUUID();j.status="QUEUED";j.requestedBy=actor;j.correlationId=correlation;j.createdAt=Instant.now();return j;}public void complete(long anomalies){status="COMPLETED";completedAt=Instant.now();summary=Map.of("anomalies",anomalies);}public UUID getId(){return id;}public String getStatus(){return status;}public String getRequestedBy(){return requestedBy;}public String getCorrelationId(){return correlationId;}}
